const $=(s,e=document)=>e.querySelector(s), $$=(s,e=document)=>[...e.querySelectorAll(s)];
const state={wizard:1,auth:'login',tab:'Resumen',selected:'C3',toastTimer:null};
const route=()=>location.pathname.replace(/\/$/,'')||'/';
const nav=(path)=>{history.pushState({},'',path);render();scrollTo(0,0)};
document.addEventListener('click',e=>{const a=e.target.closest('a[data-nav]');if(a){e.preventDefault();nav(a.getAttribute('href'))}});
window.addEventListener('popstate',render);
function showToast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}
function publicHeader(){return `<nav class="public-nav"><div class="nav-inner"><a href="/" data-nav class="logo">HumINT<span class="logo-dot"></span></a><div class="nav-links"><a data-nav class="nav-link" href="/#como">Cómo funciona</a><a data-nav class="nav-link" href="/precios">Precios</a><a data-nav class="nav-link" href="/verificar">Verificar un sello</a><a data-nav class="button secondary small" href="/acceso">Entrar</a><a data-nav class="button small" href="/acceso?modo=registro">Crear cuenta</a></div></div></nav>`}
function footer(){return `<div class="site-footer"><div class="container footer-inner"><span>HumINT · Revisión humana documentada</span><div class="footer-links"><a data-nav href="/privacidad">Privacidad</a><a data-nav href="/condiciones">Condiciones</a><a data-nav href="/aviso-legal">Aviso legal</a><span>Contacto pendiente de configuración</span></div></div>`}
const mockRows=()=>`<div class="mock-row"><span class="mock-num">C1</span><div><b>Contrastar importes</b><br><span>Revisión contable</span></div><i class="status-dot"></i></div><div class="mock-row"><span class="mock-num">C2</span><div><b>Evaluar condiciones</b><br><span>Revisión jurídica</span></div><i class="status-dot"></i></div><div class="mock-row"><span class="mock-num">C3</span><div><b>Comprobar penalización</b><br><span>Jurídica + contable</span></div><span class="badge warn">2 revisiones</span></div>`;
function home(){return `<section class="hero"><div class="container hero-stage"><div class="hero-copy"><div class="eyebrow">Revisión humana documentada</div><h1 class="display">La IA prepara. Las personas revisan.</h1><p class="lede">Sube un documento, indica para qué lo necesitas y quién debe revisarlo. HumINT te ayuda a coordinar las comprobaciones y conservar una constancia firmada.</p><div class="hero-actions"><a data-nav href="/acceso?modo=registro" class="button">Crear cuenta <span>↗</span></a><a href="#como" class="button secondary">Ver cómo funciona</a></div><p class="hero-note">Con tu equipo, tu asesor o un profesional externo.</p></div><div class="doc-stack" aria-label="Ejemplo ilustrativo de expediente"><div class="doc-card doc-under"></div><div class="doc-card doc-main"><span class="mock-label">EJEMPLO ILUSTRATIVO · VERSIÓN 3</span><h2 class="mock-title">Propuesta comercial Q4</h2>${mockRows()}</div><div class="proof-ticket"><span class="mock-label">SELLO HUMINT · EJEMPLO</span><strong>Alcance revisado</strong><p>3 puntos · 4 revisiones · 2 firmantes</p></div></div></div></section><section id="como" class="section dark"><div class="container"><div class="section-heading"><span class="eyebrow light">Cómo funciona</span><h2 class="headline">Del documento a una revisión que puedes acreditar.</h2></div><div class="steps"><article class="step"><h3>Define el encargo.</h3><p>Sube el documento, explica su finalidad e indica los perfiles expertos que crees necesarios.</p></article><article class="step"><h3>Prepara la revisión.</h3><p>La IA propone comprobaciones y perfiles. Las personas responsables confirman el plan.</p></article><article class="step"><h3>Revisa con evidencias.</h3><p>Cada experto registra sus conclusiones y solicita correcciones cuando hacen falta.</p></article><article class="step"><h3>Firma el alcance.</h3><p>Las declaraciones quedan vinculadas a la versión final del documento.</p></article></div></div></section><section class="section"><div class="container"><div class="section-heading"><span class="eyebrow">Modalidades</span><h2 class="headline">Las personas adecuadas para cada revisión.</h2></div><div class="mode-grid"><article class="mode-card"><span class="mode-index">01 / EQUIPO</span><h3>Con tu equipo.</h3><p>Asigna cada comprobación a quien tenga los conocimientos necesarios dentro de tu empresa.</p></article><article class="mode-card"><span class="mode-index">02 / CONFIANZA</span><h3>Con tu profesional.</h3><p>Invita a tu asesor o especialista a revisar un encargo concreto, sin suscripción propia.</p></article><article class="mode-card"><span class="mode-index">03 / APOYO</span><h3>Con ayuda para encontrar experto.</h3><p>Solicita un presupuesto por especialidad y alcance. Durante el piloto, la coordinación es manual.</p></article></div><p class="form-note" style="margin-top:24px">También puedes realizar una autorrevisión. El informe identificará esa modalidad.</p></div></section><section class="section alt"><div class="container"><div class="section-heading"><span class="eyebrow">Prueba de revisión</span><h2 class="headline">Una constancia que explica qué se revisó.</h2></div><div class="proof-grid"><div class="quote-panel"><span class="eyebrow light">No es una promesa universal</span><blockquote>“Versión, alcance, personas, conclusiones y firmas.”</blockquote><p>La constancia conserva el contexto necesario para interpretar el resultado.</p></div><div class="fact-panel"><span class="eyebrow">Contenido del registro</span><div class="fact"><span>Documento</span><b>Versión concreta</b></div><div class="fact"><span>Comprobaciones</span><b>Alcance confirmado</b></div><div class="fact"><span>Responsabilidad</span><b>Conclusiones personales</b></div><div class="fact"><span>Firma</span><b>Proveedor integrado</b></div><div class="alert info">El sello HumINT no es una certificación administrativa ni garantiza que no exista ningún error posible.</div></div></div></div></section><section class="section"><div class="container"><div class="section-heading"><span class="eyebrow">Preguntas breves</span><h2 class="subhead">Lo importante, sin letra pequeña.</h2></div><div class="faq"><details><summary>¿La IA aprueba el documento?</summary><p>No. La IA ayuda a preparar el plan. Las conclusiones y firmas corresponden a las personas revisoras.</p></details><details><summary>¿Necesito un experto externo?</summary><p>Puedes trabajar con tu equipo, con un profesional invitado o contigo mismo si tienes la competencia necesaria.</p></details><details><summary>¿El sello demuestra que todo es correcto?</summary><p>Permite comprobar qué revisión se documentó, sobre qué versión y con qué resultado. Consulta siempre su alcance.</p></details><details><summary>¿Puedo usar documentos creados fuera de HumINT?</summary><p>Sí. Prepara el documento con tus herramientas y súbelo para organizar la revisión.</p></details></div></div></section><section class="cta"><div class="eyebrow light">Siguiente paso</div><h2 class="headline">Antes de utilizar un documento, deja clara su revisión.</h2><a data-nav href="/acceso?modo=registro" class="button secondary">Crear cuenta</a></section>`}
function prices(){return `<section class="page-hero"><div class="container"><span class="eyebrow">Precios</span><h1 class="headline">Un espacio para coordinar y acreditar tus revisiones.</h1><p class="lede">La empresa contrata HumINT. Las personas invitadas revisan sus encargos sin tener que comprar una suscripción.</p></div></section><div class="container price-layout"><section class="price-card"><span class="eyebrow">Plan único</span><h2>Empresa</h2><p>Reúne documentos, comprobaciones, participantes y constancias en un espacio de trabajo.</p><div class="price"><b>Suscripción pendiente de configuración</b><br><small>No se muestra un importe ni checkout ficticio.</small></div><ul class="feature-list"><li>Checklist preparada con ayuda de IA</li><li>Uno o varios expertos por cada punto</li><li>Revisión interna y por invitación</li><li>Versiones, conclusiones y evidencias</li><li>Firma mediante proveedor integrado</li><li>Informe y verificación del sello HumINT</li></ul><button disabled class="button full">Elegir plan</button><p class="form-note">Los honorarios externos y cualquier firma adicional se mostrarán antes de contratar.</p></section><aside class="aside-card"><span class="eyebrow light">Revisión externa</span><h3>¿Necesitas ayuda para encontrar un experto?</h3><p>Indica la especialidad y el alcance. Recibirás un presupuesto con precio y condiciones antes de confirmar.</p><a data-nav href="/acceso?intencion=experto" class="button secondary">Preparar una solicitud</a></aside></div>`}
function access(){const reg=new URLSearchParams(location.search).get('modo')==='registro'||state.auth==='register';return `<div class="auth-wrap"><section class="auth-card"><a data-nav href="/" class="logo">HumINT<span class="logo-dot"></span></a><div class="auth-tabs"><button class="auth-tab ${!reg?'active':''}" data-auth="login">Entrar</button><button class="auth-tab ${reg?'active':''}" data-auth="register">Crear cuenta</button></div><h1>${reg?'Crea tu cuenta':'Entra en HumINT'}</h1><p>${reg?'Organiza la revisión humana de tus documentos desde un mismo lugar.':'Accede a tus documentos y a las revisiones en las que participas.'}</p><label class="field"><span>Correo electrónico</span><input type="email" placeholder="nombre@empresa.com"></label>${reg?`<label class="check"><input type="checkbox"> <span>He leído y acepto las <a data-nav href="/condiciones"><u>condiciones del servicio</u></a>. Consulta el tratamiento de datos en la <a data-nav href="/privacidad"><u>política de privacidad</u></a>.</span></label>`:''}<button class="button full" data-demo-login>${reg?'Crear cuenta y continuar':'Enviar enlace de acceso'}</button><p class="form-note">${reg?'En esta demostración no se enviará ningún mensaje.':'Recibirás un enlace para acceder a tu cuenta.'}</p></section></div>`}
function sidebar(active='Revisiones'){return `<aside class="sidebar"><a data-nav href="/app" class="logo">HumINT<span class="logo-dot" style="background:#fff"></span></a><div class="org-select">NORTE ESTUDIO <span style="float:right">⌄</span></div><a data-nav href="/app/revisiones/nueva" class="button secondary small side-primary">+ Nueva revisión</a><nav class="side-nav"><a data-nav class="${active==='Revisiones'?'active':''}" href="/app">Revisiones</a><a data-nav class="${active==='Equipo'?'active':''}" href="/app/equipo">Equipo</a><a data-nav class="${active==='Facturación'?'active':''}" href="/app/facturacion">Facturación</a><a data-nav class="${active==='Ajustes'?'active':''}" href="/app/ajustes">Ajustes</a></nav><div class="sidebar-foot">DEMO · Marta L. <span style="float:right">···</span></div></aside>`}
function shell(content,active){return `<div class="app-shell">${sidebar(active)}<div class="app-main">${content}</div></div>`}
function dashboard(){return shell(`<div class="app-top"><div><h1 class="app-title">Revisiones</h1><p class="app-desc">Consulta qué necesita atención y en qué punto está cada documento.</p></div><a data-nav href="/app/revisiones/nueva" class="button">Nueva revisión</a></div><div class="metric-grid"><div class="metric"><b>2</b><span>POR PREPARAR</span></div><div class="metric"><b>3</b><span>EN REVISIÓN</span></div><div class="metric"><b>1</b><span>PENDIENTE DE FIRMA</span></div></div><div class="tabs"><button class="tab active">Todas</button><button class="tab">Necesitan mi atención</button><button class="tab">Me corresponde revisar</button><button class="tab">Finalizadas</button></div><div class="toolbar"><input class="search-input" placeholder="Buscar por título o referencia"><button class="button secondary small">Estado ⌄</button><button class="button secondary small">Responsable ⌄</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>DOCUMENTO</th><th>VERSIÓN</th><th>RESPONSABLE</th><th>REVISIONES</th><th>FIRMAS</th><th>ESTADO</th><th>ÚLTIMA ACTIVIDAD</th></tr></thead><tbody><tr class="click-row" data-go="/app/revisiones/demo"><td><b>Propuesta comercial Q4</b><br><small>REV-2026-014</small></td><td>3</td><td>Marta L.</td><td>3 / 4</td><td>0 / 2</td><td><span class="badge warn">Cambios solicitados</span></td><td>Hace 12 min</td></tr><tr><td><b>Informe de resultados</b><br><small>REV-2026-013</small></td><td>1</td><td>Diego R.</td><td>5 / 5</td><td>1 / 2</td><td><span class="badge dark">Firmas en curso</span></td><td>Ayer</td></tr><tr><td><b>Política de proveedores</b><br><small>REV-2026-012</small></td><td>2</td><td>Marta L.</td><td>2 / 2</td><td>2 / 2</td><td><span class="badge ok">Finalizado</span></td><td>24 oct</td></tr></tbody></table></div>`, 'Revisiones')}
function wizard(){const steps=['Documento','Finalidad y contexto','Expertos previstos','Resumen'];const bodies=[`<h2>Sube el documento que quieres revisar</h2><p>La revisión quedará vinculada a esta versión. Si haces cambios, podrás subir una nueva.</p><div class="upload"><strong>Arrastra el documento aquí</strong><span>o selecciona un archivo PDF · máximo configurado por el servicio</span><br><button class="button secondary small" style="margin-top:16px" data-upload>Seleccionar archivo</button></div><div class="form-grid"><label class="field"><span>Título de la revisión</span><input value="Propuesta comercial Q4"></label><label class="field"><span>Tipo de documento</span><select><option>Propuesta comercial</option><option>Informe</option><option>Contrato</option><option>Otro / confirmar alcance</option></select></label></div><label class="field"><span>¿Se ha utilizado IA para elaborar el documento?</span><select><option>No lo sé</option><option>Sí</option><option>No</option></select></label><p class="form-note">Este dato lo declara quien sube el documento; HumINT no lo verifica automáticamente.</p>`,`<h2>Explica para qué se utilizará</h2><p>La finalidad determina qué hay que comprobar y qué conocimientos hacen falta.</p><label class="field"><span>¿Para qué se ha preparado?</span><textarea>Presentarlo a un cliente para que decida si acepta la propuesta.</textarea></label><label class="field"><span>¿Qué quieres conseguir con la revisión?</span><textarea>Contrastar las cifras, las fuentes y las condiciones que asumiríamos.</textarea></label><div class="form-grid"><label class="field"><span>Quién lo recibirá</span><select><option>Cliente o tercero identificado</option><option>Equipo interno</option><option>Público general</option></select></label><label class="field"><span>Países de uso</span><select><option>España</option><option>Necesito aclararlo</option></select></label></div><label class="field"><span>Aspectos fuera del alcance</span><input placeholder="Indica exclusiones, si existen"></label>`,`<h2>¿Qué perfiles deben participar?</h2><p>La IA propondrá qué puntos debe revisar cada uno y avisará si falta alguna especialidad.</p><div class="profile-card"><h4>01 · Contabilidad</h4><p class="form-note">Las cifras y su correspondencia con las fuentes aportadas.</p><span class="badge outline">Persona de mi equipo</span></div><div class="profile-card"><h4>02 · Derecho contractual</h4><p class="form-note">Condiciones, compromisos y penalizaciones de la propuesta.</p><span class="badge outline">Profesional externo conocido</span></div><button class="button secondary small" data-add-profile>+ Añadir perfil experto</button><div class="alert info">Un experto puede revisar varios puntos. Algunos puntos pueden necesitar más de una especialidad.</div>`,`<h2>Comprueba el encargo</h2><p>La propuesta deberá ser confirmada por las personas responsables.</p><div class="fact-panel"><div class="fact"><span>Documento</span><b>Propuesta comercial Q4 · v1</b></div><div class="fact"><span>Finalidad</span><b>Decisión de cliente</b></div><div class="fact"><span>País</span><b>España</b></div><div class="fact"><span>Perfiles previstos</span><b>Contabilidad + Derecho contractual</b></div></div><div class="alert"><b>Uso de IA</b><br>La IA preparará una propuesta de comprobaciones. No registrará decisiones humanas ni firmará por nadie.</div><label class="check"><input type="checkbox" checked><span>Confirmo que tengo autorización para compartir la información con los proveedores y participantes indicados.</span></label>`];return shell(`<div class="app-top"><div><span class="eyebrow">Borrador guardado</span><h1 class="app-title">Nueva revisión</h1></div></div><div class="wizard"><aside class="wizard-steps">${steps.map((s,i)=>`<div class="wizard-step ${state.wizard===i+1?'active':''}"><i>${i+1}</i><span>${s}</span></div>`).join('')}</aside><section><span class="eyebrow">Paso ${state.wizard} de 4</span>${bodies[state.wizard-1]}<div class="actions"><button class="button secondary" data-prev ${state.wizard===1?'disabled':''}>Atrás</button>${state.wizard<4?`<button class="button" data-next>Continuar</button>`:`<div><button class="button secondary" data-save>Guardar borrador</button> <button class="button" data-prepare>Preparar checklist</button></div>`}</div></section></div>`,'Revisiones')}
const itemData={C1:['Contrastar importes con las fuentes','Contabilidad','Ana M.','Verificado'],C2:['Evaluar las condiciones contractuales','Derecho contractual','Luis G.','Pendiente'],C3:['Comprobar una penalización y su cálculo','Jurídica + contable','Luis G. + Ana M.','2 revisiones']};
function plan(){return shell(`<div class="app-top"><div><span class="badge warn">Propuesta con IA · pendiente de confirmación</span><h1 class="app-title" style="margin-top:16px">Confirma el plan de revisión</h1><p class="app-desc">Revisa el reparto, resuelve las carencias y confirma el alcance.</p></div><button class="button" data-confirm-plan>Confirmar propuesta</button></div><div class="metric-grid"><div class="metric"><b>3</b><span>PUNTOS</span></div><div class="metric"><b>4</b><span>REVISIONES REQUERIDAS</span></div><div class="metric"><b>1</b><span>CARENCIA POR RESOLVER</span></div></div><div class="review-layout"><div class="checklist">${Object.entries(itemData).map(([id,d])=>`<div class="check-item ${state.selected===id?'active':''}" data-item="${id}"><small>${id} · ${d[1]}</small><b>${d[0]}</b><br><span class="badge ${id==='C3'?'warn':''}" style="margin-top:10px">${d[3]}</span></div>`).join('')}</div><div class="check-detail"><span class="eyebrow">${state.selected} · Ficha de comprobación</span><h2>${itemData[state.selected][0]}</h2><div class="info-grid"><div class="info-box"><small>POR QUÉ SE INCLUYE</small><b>Compromiso económico relevante para la decisión.</b></div><div class="info-box"><small>DÓNDE APARECE</small><b>Página 8 · cláusula 4.2</b></div><div class="info-box"><small>PERFILES NECESARIOS</small><b>${itemData[state.selected][1]}</b></div><div class="info-box"><small>PERSONA PREVISTA</small><b>${itemData[state.selected][2]}</b></div></div><h3>Resumen del contexto <span class="badge outline">Preparado con IA</span></h3><p class="form-note">Utiliza este resumen para orientarte. Consulta el documento y las fuentes para llegar a tu propia conclusión.</p>${state.selected==='C3'?`<div class="alert"><b>Especialidad adicional detectada</b><br>Este punto necesita una revisión contable y otra jurídica. La primera no completa la segunda.<br><button class="button secondary small" style="margin-top:12px" data-resolve>Añadir perfil</button></div>`:''}<div class="actions"><button class="button secondary small">Editar comprobación</button><button class="button small" data-assign>Asignar persona</button></div></div></div>`,'Revisiones')}
function review(){const tabs=['Resumen','Checklist','Participantes','Versiones','Historial'];let content='';if(state.tab==='Resumen')content=`<div class="metric-grid"><div class="metric"><b>3/4</b><span>REVISIONES REALIZADAS</span></div><div class="metric"><b>2/4</b><span>REVISIONES FAVORABLES</span></div><div class="metric"><b>0/2</b><span>FIRMAS</span></div></div><div class="content-card"><h2>Estado de la revisión</h2><div class="alert">Hay una comprobación que necesita correcciones y una revisión jurídica pendiente.</div><div class="fact"><span>Finalidad</span><b>Decisión de un cliente identificado</b></div><div class="fact"><span>Alcance confirmado</span><b>3 puntos · 4 revisiones</b></div><div class="fact"><span>Responsable</span><b>Marta López</b></div><div class="fact"><span>Autorización de uso final</span><b>Pendiente</b></div></div>`;if(state.tab==='Checklist')content=`<div class="review-layout"><div class="checklist">${Object.entries(itemData).map(([id,d])=>`<div class="check-item ${state.selected===id?'active':''}" data-item="${id}"><small>${id} · ${d[1]}</small><b>${d[0]}</b></div>`).join('')}</div><div class="check-detail"><span class="badge outline">Tu comprobación · ${itemData[state.selected][1]}</span><h2>${itemData[state.selected][0]}</h2><label class="field"><span>¿Cuál es tu conclusión?</span><select><option>Selecciona una conclusión</option><option>Verificado para el alcance indicado</option><option>Requiere cambios</option><option>No puedo verificarlo con la información disponible</option></select></label><label class="field"><span>Explica tu conclusión</span><textarea placeholder="Registra la conclusión a la que has llegado…"></textarea></label><label class="field"><span>Fuentes consultadas</span><input placeholder="Añade referencias o enlaces"></label><div class="actions"><button class="button secondary" data-save>Guardar borrador</button><button class="button" data-conclusion>Registrar conclusión</button></div></div></div>`;if(state.tab==='Participantes')content=`<div class="content-card"><div class="app-top"><h2>Quién revisa cada parte</h2><button class="button small" data-invite>Invitar persona</button></div><div class="fact"><span>Ana Martín · Contabilidad</span><b>C1, C3 · Alcance aceptado</b></div><div class="fact"><span>Luis García · Derecho contractual</span><b>C2, C3 · Pendiente</b></div><div class="alert info">Correo confirmado, identidad y competencias se muestran por separado cuando existe evidencia.</div></div>`;if(state.tab==='Versiones')content=`<div class="content-card"><h2>Versiones del documento</h2><p>Cada revisión y firma se vincula a una versión concreta.</p><div class="fact"><span>Versión 3 · 27 oct 2026</span><b>Actual · En revisión</b></div><div class="fact"><span>Versión 2 · 25 oct 2026</span><b>Cambios solicitados</b></div><div class="fact"><span>Versión 1 · 23 oct 2026</span><b>Archivada</b></div><button class="button secondary small" data-new-version>Subir nueva versión</button></div>`;if(state.tab==='Historial')content=`<div class="content-card"><h2>Actividad del expediente</h2>${['Marta subió la versión 3','Ana registró una conclusión contable','Luis solicitó información adicional','El servicio preparó una propuesta con IA'].map((x,i)=>`<div class="fact"><span>${x}</span><b>${12+i*18} min</b></div>`).join('')}</div>`;return shell(`<div class="app-top"><div><span class="badge warn">Cambios solicitados</span><h1 class="app-title" style="margin-top:14px">Propuesta comercial Q4</h1><p class="app-desc">Versión 3 · Norte Estudio · Revisión con equipo y profesional invitado</p></div><a data-nav href="/app/revisiones/demo/firma" class="button secondary">Firma y cierre</a></div><div class="tabs">${tabs.map(t=>`<button class="tab ${state.tab===t?'active':''}" data-review-tab="${t}">${t}</button>`).join('')}</div>${content}`,'Revisiones')}
function signing(){return shell(`<div class="app-top"><div><span class="eyebrow">Versión 3</span><h1 class="app-title">Firma y cierre</h1><p class="app-desc">Prepara las declaraciones sobre una versión concreta.</p></div></div><div class="content-card" style="max-width:850px"><div class="alert dark">SIMULACIÓN · Proveedor de firma pendiente de configuración</div><h2>Paquete de firma</h2><div class="fact"><span>Documento</span><b>Propuesta comercial Q4 · v3</b></div><div class="fact"><span>Revisiones registradas</span><b>3 de 4</b></div><div class="fact"><span>Firmantes preparados</span><b>1 de 2</b></div><div class="alert">No puede enviarse a firma: falta la conclusión jurídica del punto C3. Una redirección del navegador nunca confirma una firma.</div><button disabled class="button">Enviar al proveedor de firma</button><a data-nav href="/app/revisiones/demo/resultado" class="button secondary" style="margin-left:8px">Ver resultado simulado</a></div>`,'Revisiones')}
