function verify(){const has=route()!='/verificar';return `<section class="verification"><a data-nav href="/" class="logo">HumINT<span class="logo-dot"></span></a>${has?`<div class="seal"><div><b>HumINT</b><small>EJEMPLO DE PRUEBA</small></div></div><div class="center"><span class="badge warn">Registro de prueba · no acredita una revisión real</span><h1 class="subhead" style="margin:24px 0">Propuesta comercial Q4</h1><p>Versión 3 · Resultado con limitaciones</p></div><div class="fact-panel"><div class="fact"><span>Código</span><b>DEMO-7K2P</b></div><div class="fact"><span>Alcance visible</span><b>3 puntos · 4 revisiones</b></div><div class="fact"><span>Firmas</span><b>No completadas</b></div><div class="fact"><span>Comprobación técnica</span><b>Pendiente de configuración</b></div></div>`:`<div style="padding-top:80px"><span class="eyebrow">Verificar un sello</span><h1 class="headline">Comprueba el alcance de una revisión.</h1><p class="lede">Introduce el código o pega el enlace que acompaña al sello.</p><label class="field"><span>Código de verificación</span><input id="verify-code" placeholder="Ej. ABCD-1234"></label><button class="button" data-verify>Comprobar código</button><div class="alert info">La consulta no revela documentos privados ni confirma si existe un expediente restringido.</div></div>`}</section>`}
