const legalData={"/privacidad":['Política de privacidad','Esta página es una base de maquetación y requiere completar la identidad, proveedores, ubicaciones y plazos reales.',['Responsable y contacto','Datos de la cuenta y del servicio','Documentos tratados por cuenta de las empresas','Finalidades y bases jurídicas','Proveedores y destinatarios','Conservación y derechos']],"/condiciones":['Condiciones del servicio','HumINT facilita la preparación y coordinación de revisiones, el registro de conclusiones y la recogida de firmas mediante proveedores integrados.',['Quién presta el servicio','Usuarios y permisos','Funcionamiento de las revisiones','Propuestas generadas con IA','Firmas y evidencias','Precio, renovación y presupuestos','Uso del sello']],"/aviso-legal":['Aviso legal','Los datos de razón social, identificación fiscal, domicilio y contacto están pendientes de configuración.',['Identificación del titular','Contacto','Propiedad intelectual','Uso del sitio','Enlaces a terceros']]};
