function render(){const p=route();let view,publicPage=true;if(p==='/')view=home();else if(p==='/precios')view=prices();else if(p==='/acceso')view=access();else if(p==='/bienvenida')view=welcome();else if(p.startsWith('/invitaciones/'))view=invitation();else if(p.startsWith('/verificar'))view=verify();else if(legalData[p])view=legal();else if(p==='/operaciones'){view=operations();publicPage=false}else if(p==='/app'){view=dashboard();publicPage=false}else if(p==='/app/equipo'){view=team();publicPage=false}else if(p==='/app/ajustes'){view=settings();publicPage=false}else if(p==='/app/facturacion'){view=billing();publicPage=false}else if(p==='/app/revisiones/nueva'){view=wizard();publicPage=false}else if(p.endsWith('/plan')){view=plan();publicPage=false}else if(p.endsWith('/firma')){view=signing();publicPage=false}else if(p.endsWith('/resultado')){view=result();publicPage=false}else if(/^\/app\/revisiones\/[^/]+$/.test(p)){view=review();publicPage=false}else{view=generic();publicPage=false}$('#site-header').innerHTML=publicPage&&!['/acceso','/bienvenida'].includes(p)&&!p.startsWith('/invitaciones')&&!p.startsWith('/verificar')&&!legalData[p]?publicHeader():'';$('#site-footer').innerHTML=publicPage&&!['/acceso','/bienvenida'].includes(p)&&!p.startsWith('/invitaciones')&&!p.startsWith('/verificar')&&!legalData[p]?footer():'';$('#app').innerHTML=view;bind()}
function bind(){$$('[data-auth]').forEach(b=>b.onclick=()=>{state.auth=b.dataset.auth==='register'?'register':'login';history.replaceState({},'',state.auth==='register'?'/acceso?modo=registro':'/acceso');render()});$('[data-demo-login]')?.addEventListener('click',()=>showToast('Demostración: no se ha enviado ningún correo.'));$('[data-upload]')?.addEventListener('click',()=>showToast('Archivo de ejemplo seleccionado · propuesta-q4.pdf'));$('[data-next]')?.addEventListener('click',()=>{state.wizard++;render()});$('[data-prev]')?.addEventListener('click',()=>{state.wizard--;render()});$('[data-prepare]')?.addEventListener('click',()=>nav('/app/revisiones/demo/plan'));$$('[data-item]').forEach(x=>x.onclick=()=>{state.selected=x.dataset.item;render()});$$('[data-review-tab]').forEach(x=>x.onclick=()=>{state.tab=x.dataset.reviewTab;render()});$$('[data-save]').forEach(x=>x.onclick=()=>showToast('Cambios guardados en esta demostración.'));$('[data-add-profile]')?.addEventListener('click',()=>showToast('Perfil añadido a la propuesta.'));$('[data-confirm-plan]')?.addEventListener('click',()=>showToast('Propuesta confirmada por la persona responsable.'));$('[data-resolve]')?.addEventListener('click',()=>showToast('Carencia marcada para asignación.'));$('[data-assign]')?.addEventListener('click',()=>showToast('Selector de persona abierto en la versión completa.'));$('[data-conclusion]')?.addEventListener('click',()=>showToast('Conclusión simulada registrada para la versión 3.'));$('[data-invite]')?.addEventListener('click',()=>showToast('Invitación preparada; no se ha enviado ningún correo.'));$('[data-new-version]')?.addEventListener('click',()=>showToast('La nueva versión tendrá su propia revisión.'));$('[data-print]')?.addEventListener('click',()=>showToast('Informe de prueba preparado.'));$('[data-verify]')?.addEventListener('click',()=>nav('/verificar/DEMO-7K2P'));$('[data-create-space]')?.addEventListener('click',()=>nav('/app'));$('[data-accept]')?.addEventListener('click',()=>nav('/app/revisiones/demo'));$$('[data-go]').forEach(x=>x.onclick=()=>nav(x.dataset.go))}
function publicHeaderV2(){return `<nav class="public-nav"><div class="nav-inner"><a href="/" data-nav class="logo">HumINT<span class="logo-dot"></span></a><div class="nav-links"><a class="nav-link" href="#como">Cómo funciona</a><a data-nav class="nav-link" href="/precios">Precios</a><a data-nav class="nav-link" href="/verificar">Verificar un sello</a><a data-nav class="button secondary small" href="/acceso">Entrar</a><a data-nav class="button small" href="/acceso?modo=registro">Crear cuenta</a></div></div></nav>`}

function homeV2(){return `<div class="home-v2"><section class="cosmos-journey" aria-label="Del documento a una revisión verificable"><div class="cosmos-sticky"><div class="space-frame" id="space-frame"><canvas class="cosmos-canvas" id="cosmos-canvas" aria-hidden="true"></canvas><div class="cosmos-grain"></div><div class="cosmos-hero-copy"><span class="eyebrow">Revisión humana documentada</span><h1>La IA prepara.<br>Las personas revisan.</h1><p class="lede">Coordina las comprobaciones, las evidencias y las firmas de una versión concreta, en un solo lugar.</p><div class="hero-actions"><a data-nav href="/acceso?modo=registro" class="button">Crear cuenta <span>↗</span></a><a href="#como" class="button secondary">Ver cómo funciona</a></div><div class="journey-prompt">Desliza para alejar la mirada</div></div><img class="earth-photo" id="earth-photo" src="/assets/earth-photoreal-v2.png" alt="La Tierra vista desde el espacio"><div class="space-message" data-space-phase="one"><span class="eyebrow">Más perspectiva. Más precisión.</span><h2>Aleja la mirada.<br>Acerca la evidencia.</h2><p>La confianza no nace de una promesa. Nace de saber quién revisó, qué comprobó y sobre qué versión.</p></div><div class="space-message shape-copy" data-space-phase="two"><span class="eyebrow">Una constelación verificable</span><h2>Cada punto deja una trazabilidad clara.</h2><p>Persona responsable, especialidad, conclusión, evidencia y firma. Las estrellas se ordenan; el proceso también.</p></div><div class="space-message exit-copy" data-space-phase="exit"><span class="eyebrow">HumINT</span><h2>Sales del ruido.<br>Entras en un proceso claro.</h2><p>La IA propone. Las personas confirman. El resultado conserva su contexto.</p></div><div class="journey-counter"><span id="journey-step">01</span> / 04</div></div></div></section><section id="como" class="minimal-process"><div class="container"><div class="process-intro"><span class="eyebrow">Cómo funciona</span><h2>Cuatro pasos.<br>Ninguna caja negra.</h2></div><div class="process-grid"><article class="process-row"><span class="process-no">01</span><h3>Define el encargo.</h3><p>Sube el documento, explica su finalidad e indica los perfiles que deben participar.</p></article><article class="process-row"><span class="process-no">02</span><h3>Prepara el alcance.</h3><p>La IA propone comprobaciones y reparto. Las personas responsables revisan y confirman el plan.</p></article><article class="process-row"><span class="process-no">03</span><h3>Revisa con evidencias.</h3><p>Cada especialista registra su propia conclusión, sus fuentes y las limitaciones detectadas.</p></article><article class="process-row"><span class="process-no">04</span><h3>Firma una versión.</h3><p>Las declaraciones se vinculan a la versión final y pueden consultarse dentro del alcance autorizado.</p></article></div></div></section><section class="evidence-section"><div class="container"><div class="evidence-head"><h2>Una revisión que se puede explicar.</h2><div><span class="eyebrow light">No es un sello vacío</span><p>HumINT conserva el documento, los puntos comprobados, las personas revisoras, sus conclusiones y las firmas asociadas. El resultado se interpreta siempre dentro de su alcance.</p></div></div><div class="evidence-demo"><div class="evidence-doc"><span class="eyebrow light">Ejemplo ilustrativo · Versión 3</span><h3>Propuesta comercial Q4</h3><div class="review-line"><span>C1</span><div><b>Contrastar importes</b><br><small>Revisión contable</small></div><i class="badge ok">Favorable</i></div><div class="review-line"><span>C2</span><div><b>Evaluar condiciones</b><br><small>Revisión jurídica</small></div><i class="badge outline">Pendiente</i></div><div class="review-line"><span>C3</span><div><b>Comprobar penalización</b><br><small>Contable + jurídica</small></div><i class="badge warn">2 revisiones</i></div></div><aside class="evidence-proof"><div class="seal-orbit"><div><b>HumINT</b><small>EJEMPLO</small></div></div><div><span class="eyebrow">Constancia de revisión</span><h3>Alcance, personas y versión.</h3><p class="form-note">El sello HumINT no es una certificación administrativa ni garantiza que no exista ningún error posible.</p></div></aside></div></div></section><section class="section alt"><div class="container"><div class="section-heading"><span class="eyebrow">Modalidades</span><h2 class="headline">Con tu equipo, tu profesional o un experto externo.</h2></div><div class="mode-grid"><article class="mode-card"><span class="mode-index">01 / EQUIPO</span><h3>Personas de tu empresa.</h3><p>Asigna cada comprobación a quien tenga los conocimientos necesarios.</p></article><article class="mode-card"><span class="mode-index">02 / CONFIANZA</span><h3>Tu asesor habitual.</h3><p>Invita a un especialista a un encargo concreto, sin darle acceso a todo el espacio.</p></article><article class="mode-card"><span class="mode-index">03 / APOYO</span><h3>Ayuda para encontrar experto.</h3><p>Solicita un presupuesto por especialidad y alcance antes de contratar.</p></article></div></div></section><section class="home-end"><span class="eyebrow">Siguiente paso</span><h2>Antes de utilizar un documento, deja clara su revisión.</h2><p>Empieza con un borrador. Invita a las personas adecuadas cuando el alcance esté preparado.</p><a data-nav href="/acceso?modo=registro" class="button">Crear cuenta</a></section></div>`}

function initCosmos(){
  const section=$('.cosmos-journey'), frame=$('#space-frame'), earth=$('#earth-photo'), canvas=$('#cosmos-canvas'), hero=$('.cosmos-hero-copy'), counter=$('#journey-step');
  if(!section||!frame||!canvas)return ()=>{};
  const ctx=canvas.getContext('2d'), phases={one:$('[data-space-phase="one"]'),two:$('[data-space-phase="two"]'),exit:$('[data-space-phase="exit"]')};
  let w=0,h=0,dpr=1,stars=[],raf=0;
  const clamp=(n,a=0,b=1)=>Math.max(a,Math.min(b,n)), ease=n=>n*n*(3-2*n), peak=(p,a,b,c,d)=>clamp((p-a)/(b-a))*clamp((d-p)/(d-c));
  function resize(){dpr=Math.min(devicePixelRatio||1,2);w=frame.clientWidth;h=frame.clientHeight;canvas.width=w*dpr;canvas.height=h*dpr;canvas.style.width=w+'px';canvas.style.height=h+'px';ctx.setTransform(dpr,0,0,dpr,0,0);const count=Math.min(420,Math.max(190,Math.floor(w*h/3600)));stars=Array.from({length:count},(_,i)=>({x:Math.random()*w,y:Math.random()*h,r:.45+Math.random()*1.25,t:Math.random()*6.28,i}));draw(0)}
  function targetFor(s){const cx=w>(800)?w*.76:w*.5,cy=h*.5,scale=Math.min(w,h)*(w>800?.48:.42),n=s.i/stars.length;if(n<.68){const q=n/.68,side=Math.floor(q*4),u=(q*4)%1,hw=scale*.34,hh=scale*.46;if(side===0)return[cx-hw+u*hw*2,cy-hh];if(side===1)return[cx+hw,cy-hh+u*hh*2];if(side===2)return[cx+hw-u*hw*2,cy+hh];return[cx-hw,cy+hh-u*hh*2]}const q=(n-.68)/.32;if(q<.44)return[cx-scale*.19+q/.44*scale*.17,cy+scale*.05+q/.44*scale*.17];return[cx-scale*.02+(q-.44)/.56*scale*.34,cy+scale*.22-(q-.44)/.56*scale*.36]}
  function draw(morph){ctx.clearRect(0,0,w,h);const now=performance.now()*.001;stars.forEach(s=>{const [tx,ty]=targetFor(s),m=ease(morph),x=s.x+(tx-s.x)*m,y=s.y+(ty-s.y)*m,tw=.68+.32*Math.sin(now+s.t);ctx.beginPath();ctx.arc(x,y,s.r*tw+(m*.25),0,Math.PI*2);ctx.fillStyle=`rgba(255,255,255,${.38+tw*.52})`;ctx.fill()})}
  function update(){raf=0;const rect=section.getBoundingClientRect(),total=Math.max(1,section.offsetHeight-innerHeight),p=clamp(-rect.top/total),dark=ease(clamp((p-.08)/.12)),frameP=ease(clamp((p-.79)/.18));frame.style.backgroundColor=`rgb(${Math.round(255-(250*dark))},${Math.round(255-(250*dark))},${Math.round(255-(250*dark))})`;frame.style.color=dark>.35?'#fff':'#050505';frame.style.transform=`scale(${1-frameP*.11})`;frame.style.borderRadius=`${frameP*30}px`;canvas.style.opacity=clamp((p-.12)/.12)*(.72+frameP*.2);hero.style.opacity=1-ease(clamp((p-.03)/.16));hero.style.transform=`translateX(-50%) translateY(${-p*38}px)`;const earthScale=1-ease(clamp(p/.58))*.76,earthY=-ease(clamp(p/.64))*48;earth.style.transform=`translate(-50%,${earthY}vh) scale(${earthScale})`;earth.style.opacity=1-ease(clamp((p-.47)/.2));phases.one.style.opacity=peak(p,.24,.32,.43,.5);phases.two.style.opacity=peak(p,.45,.53,.66,.75);phases.exit.style.opacity=clamp((p-.77)/.1);counter.textContent=p<.2?'01':p<.45?'02':p<.76?'03':'04';draw(clamp((p-.44)/.25));}
  const schedule=()=>{if(!raf)raf=requestAnimationFrame(update)};resize();update();addEventListener('scroll',schedule,{passive:true});addEventListener('resize',resize);return()=>{removeEventListener('scroll',schedule);removeEventListener('resize',resize);if(raf)cancelAnimationFrame(raf)}
}

